import 'package:flutter_test/flutter_test.dart';
import 'package:servnova_mobile/core/l10n/strings.dart';
import 'package:servnova_mobile/main.dart';

/// Smoke test. (Replaces the counter test generated by `flutter create`,
/// which referred to a `MyApp` that does not exist.)
void main() {
  setUpAll(() async {
    TestWidgetsFlutterBinding.ensureInitialized();
    await Strings.load();
  });

  testWidgets('without a valid configuration the app says so instead of crashing', (tester) async {
    await tester.pumpWidget(const ServNovaApp(deps: null));
    expect(find.text(Strings.error('CONFIG')), findsOneWidget);
  });
}
